#include <acpi/acpi_table.h>
#include <asm/acpi_table.h>
#include <linux/sizes.h>
#include <linux/string.h>
#include "../model.h"

#define J413_UART_BASE	0x235200000ULL
#define J413_AIC_BASE	0x23b0c0000ULL
#define J413_UART_PATH	"\\_SB.UART"

/* Generated by iasl from dsdt.asl. */
extern const u8 apple_j413_dsdt[];

struct j413_csrt_aic {
	struct acpi_csrt_group group;
	struct acpi_csrt_shared_info shared;
	struct acpi_csrt_descriptor descriptor;
	u32 device_info;
} __packed;

static void j413_fill_fadt(struct acpi_fadt *fadt)
{
	fadt->flags = ACPI_FADT_HW_REDUCED_ACPI;
	fadt->preferred_pm_profile = ACPI_PM_MOBILE;
	fadt->arm_boot_arch = ACPI_ARM_PSCI_COMPLIANT;
}

static void j413_fill_madt(struct acpi_ctx *ctx)
{
	static const u64 mpidrs[] = {
		0, 1, 2, 3, 0x10100, 0x10101, 0x10102, 0x10103,
	};
	struct acpi_madt_gicc *gicc;
	int i;

	for (i = 0; i < ARRAY_SIZE(mpidrs); i++) {
		gicc = ctx->current;
		/* Higher efficiency-class numbers denote higher performance. */
		acpi_write_madt_gicc(gicc, i, 0x17, 0, 0, 0, 0x19, 0,
				     mpidrs[i], i < 4 ? 0 : 1);
		acpi_inc(ctx, sizeof(*gicc));
	}
}

static int j413_fill_csrt(struct acpi_ctx *ctx)
{
	struct j413_csrt_aic *aic = ctx->current;

	memset(aic, 0, sizeof(*aic));
	aic->group.length = sizeof(*aic);
	memcpy(&aic->group.vendor_id, "AAPL", 4);
	aic->group.device_id = 0x100a;
	aic->group.revision = 2;
	aic->group.shared_info_length = sizeof(aic->shared);
	aic->shared.major_version = 2;
	aic->shared.mmio_base_low = lower_32_bits(J413_AIC_BASE);
	aic->shared.mmio_base_high = upper_32_bits(J413_AIC_BASE);
	aic->descriptor.length = sizeof(aic->descriptor) + sizeof(aic->device_info);
	aic->descriptor.type = ACPI_CSRT_TYPE_INTERRUPT;
	aic->descriptor.subtype = ACPI_CSRT_INTERRUPT_CONTROLLER;
	acpi_inc(ctx, sizeof(*aic));

	return 0;
}

static int j413_write_gtdt(struct acpi_ctx *ctx, const struct acpi_writer *entry)
{
	struct acpi_gtdt *gtdt = ctx->current;
	const u32 size = offsetof(struct acpi_gtdt, virt_el2_gsiv);

	memset(gtdt, 0, size);
	acpi_fill_header(&gtdt->header, "GTDT");
	gtdt->header.length = size;
	gtdt->header.revision = 2;
	gtdt->cnt_ctrl_base = ~0ULL;
	gtdt->cnt_read_base = ~0ULL;
	gtdt->sec_el1_gsiv = 0x1d;
	gtdt->sec_el1_flags = GTDT_FLAG_ALWAYS_ON;
	gtdt->el1_gsiv = 0x1e;
	gtdt->el1_flags = GTDT_FLAG_ALWAYS_ON;
	gtdt->virt_el1_gsiv = 0x1b;
	gtdt->virt_el1_flags = GTDT_FLAG_ALWAYS_ON;
	gtdt->el2_gsiv = 0x1a;
	gtdt->el2_flags = GTDT_FLAG_ALWAYS_ON;
	acpi_update_checksum(&gtdt->header);
	acpi_inc(ctx, size);

	return acpi_add_table(ctx, gtdt);
}

static int j413_write_dbg2(struct acpi_ctx *ctx, const struct acpi_writer *entry)
{
	struct acpi_dbg2_header *dbg2 = ctx->current;
	struct acpi_gen_regaddr address = {
		.space_id = ACPI_ADDRESS_SPACE_MEMORY,
		.bit_width = 32,
		.access_size = ACPI_ACCESS_SIZE_DWORD_ACCESS,
		.addrl = lower_32_bits(J413_UART_BASE),
		.addrh = upper_32_bits(J413_UART_BASE),
	};

	acpi_create_dbg2(dbg2, ACPI_DBG2_SERIAL_PORT, ACPI_DBG2_APPLE_S5L,
			 &address, SZ_4K, J413_UART_PATH);
	acpi_inc(ctx, dbg2->header.length);

	return acpi_add_table(ctx, dbg2);
}

APPLE_ACPI_MODEL(j413) = {
	.compatible = "apple,j413",
	.dsdt = apple_j413_dsdt,
	.table_size = SZ_64K,
	.fill_fadt = j413_fill_fadt,
	.fill_madt = j413_fill_madt,
	.fill_csrt = j413_fill_csrt,
	.write_gtdt = j413_write_gtdt,
	.write_dbg2 = j413_write_dbg2,
};
